param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$providers=[Text.EncodingProvider].GetField('s_providers',[Reflection.BindingFlags]'Static,NonPublic');if($null -eq $providers -or $providers.IsInitOnly -or $providers.FieldType -ne [Text.EncodingProvider[]]){throw 'Pinned provider state shape changed'}
$hostProviders=@($providers.GetValue($null)|ForEach-Object {$_.GetType().AssemblyQualifiedName});$providers.SetValue($null,$null)
if([Text.Encoding]::GetEncoding(0).CodePage -ne 65001 -or -not [object]::ReferenceEquals([Text.Encoding]::GetEncoding(0),[Text.Encoding]::Default)){throw 'Provider-free lookup isolation failed'}
function Unwrap($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};return $e}
function ErrorRecord($errorValue){$e=Unwrap $errorValue;return [ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;message=$e.Message;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
function EncoderValue([int]$id){switch($id){0{return $null}1{return [Text.EncoderReplacementFallback]::new('?')}2{return [Text.EncoderReplacementFallback]::new('XY')}3{return [Text.EncoderReplacementFallback]::new('')}4{return [Text.EncoderFallback]::ExceptionFallback}default{throw 'Encoder profile'}}}
function DecoderValue([int]$id){switch($id){0{return $null}1{return [Text.DecoderReplacementFallback]::new('?')}2{return [Text.DecoderReplacementFallback]::new('XY')}3{return [Text.DecoderReplacementFallback]::new('')}4{return [Text.DecoderFallback]::ExceptionFallback}default{throw 'Decoder profile'}}}
function Units([string]$value){return ,([int[]]@($value.ToCharArray()|ForEach-Object {[int]$_}))}
$aliases=@('unicode-1-1-utf-8','unicode-2-0-utf-8','utf-8','x-unicode-1-1-utf-8','x-unicode-2-0-utf-8')
$otherNames=@('ansi_x3.4-1968','ansi_x3.4-1986','ascii','cp367','cp819','csascii','csisolatin1','csunicode11utf7','ibm367','ibm819','iso-10646-ucs-2','iso-8859-1','iso-ir-100','iso-ir-6','iso646-us','iso8859-1','iso_646.irv:1991','iso_8859-1','iso_8859-1:1987','l1','latin1','ucs-2','unicode','unicode-1-1-utf-7','unicode-2-0-utf-7','unicodefffe','us','us-ascii','utf-16','utf-16be','utf-16le','utf-32','utf-32be','utf-32le','utf-7','x-unicode-1-1-utf-7','x-unicode-2-0-utf-7')
$requests=[Collections.Generic.List[object]]::new();foreach($codepage in @([int]::MinValue,-65536,-1,0,1,2,3,42,1200,1201,12000,12001,20127,28591,65000,65001,65535,65536,[int]::MaxValue)){$requests.Add([ordered]@{kind='number';codepage=$codepage;name=$null;candidateScope=$(if($codepage -eq 0 -or $codepage -eq 65001 -or $codepage -lt 0 -or $codepage -gt 65535 -or $codepage -in 1,2,3,42){'differential'}else{'unsupported-boundary'})})}
$names=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($name in $aliases+$otherNames){[void]$names.Add($name);[void]$names.Add($name.ToUpperInvariant());for($i=0;$i -lt $name.Length;$i++){if([char]::IsAsciiLetterLower($name[$i])){[void]$names.Add($name.Substring(0,$i)+[char]::ToUpperInvariant($name[$i])+$name.Substring($i+1))}}}
foreach($name in @('',' ','utf8','UTF8','65001','cp65001',' utf-8','utf-8 ',"utf-8`0",'utf_8',('UTF'+[char]0x2013+'8'),'utf-9','default','x-utf-8',"`tutf-8",'unicode-1-1-UTF_8',([string][char]0xD800),(([string][char]0x0130)+'utf-8'))){[void]$names.Add($name)}
$requests.Add([ordered]@{kind='name';codepage=0;name=$null;candidateScope='differential'});foreach($name in ($names|Sort-Object -CaseSensitive)){$requests.Add([ordered]@{kind='name';codepage=0;name=$name;candidateScope=$(if($otherNames -contains $name){'unsupported-boundary'}else{'differential'})})}
$methods=@{number=[Text.Encoding].GetMethod('GetEncoding',[type[]]@([int]));name=[Text.Encoding].GetMethod('GetEncoding',[type[]]@([string]));numberFallback=[Text.Encoding].GetMethod('GetEncoding',[type[]]@([int],[Text.EncoderFallback],[Text.DecoderFallback]));nameFallback=[Text.Encoding].GetMethod('GetEncoding',[type[]]@([string],[Text.EncoderFallback],[Text.DecoderFallback]))}
$rows=[Collections.Generic.List[object]]::new();foreach($request in $requests){$configs=[Collections.Generic.List[object]]::new();$configs.Add(@(-1,-1));foreach($enc in 0..4){foreach($dec in 0..4){$configs.Add(@($enc,$dec))}};foreach($config in $configs){$enc=[int]$config[0];$dec=[int]$config[1];$ef=$null;$df=$null;$argsValue=[object[]]::new($(if($enc -lt 0){1}else{3}));if($request.kind -eq 'number'){$argsValue[0]=[int]$request.codepage}elseif($null -eq $request.name){$argsValue[0]=$null}else{$argsValue[0]=[string]$request.name};$key=$request.kind;if($enc -ge 0){$ef=EncoderValue $enc;$df=DecoderValue $dec;$argsValue[1]=[Text.EncoderFallback]$ef;$argsValue[2]=[Text.DecoderFallback]$df;$key+='Fallback'}
 try{$encoding=[Text.Encoding]$methods[$key].Invoke($null,$argsValue);$second=[Text.Encoding]$methods[$key].Invoke($null,$argsValue);$result=[ordered]@{ok=$true;codepage=$encoding.CodePage;readOnly=$encoding.IsReadOnly;preamble=[int[]]$encoding.GetPreamble();sameRepeated=[object]::ReferenceEquals($encoding,$second);sameUtf8=[object]::ReferenceEquals($encoding,[Text.Encoding]::UTF8);sameDefault=[object]::ReferenceEquals($encoding,[Text.Encoding]::Default);encoderSameInput=[object]::ReferenceEquals($encoding.EncoderFallback,$ef);decoderSameInput=[object]::ReferenceEquals($encoding.DecoderFallback,$df);encoderType=$encoding.EncoderFallback.GetType().FullName;decoderType=$encoding.DecoderFallback.GetType().FullName;encoderMax=$encoding.EncoderFallback.MaxCharCount;decoderMax=$encoding.DecoderFallback.MaxCharCount;operations=@()}
 if($request.candidateScope -eq 'differential'){$ops=[Collections.Generic.List[object]]::new();foreach($text in @('', 'A',([string][char]0xD800),(([string][char]0xD800)+'A'),(([string][char]0xD83D)+([string][char]0xDE00)))){try{$value=[int[]]$encoding.GetBytes($text);$op=[ordered]@{ok=$true;value=$value}}catch{$op=ErrorRecord $_.Exception};$ops.Add([ordered]@{kind='encode';input=(Units $text);result=$op})};foreach($bytes in @([byte[]]@(),[byte[]]@(65),[byte[]]@(255),[byte[]]@(226,130),[byte[]]@(240,159,152,128))){try{$value=Units ($encoding.GetString([byte[]]$bytes));$op=[ordered]@{ok=$true;value=$value}}catch{$op=ErrorRecord $_.Exception};$ops.Add([ordered]@{kind='decode';input=[int[]]$bytes;result=$op})};$result.operations=$ops.ToArray()}
 }catch{$result=ErrorRecord $_.Exception};$rows.Add([ordered]@{request=$request;encoderProfile=$enc;decoderProfile=$dec;result=$result})
}}
if($null -ne $providers.GetValue($null)){throw 'Provider registration changed during capture'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();providerIsolation=[ordered]@{removedHostProviders=$hostProviders;field='System.Text.EncodingProvider.s_providers';scope='THIS_DISPOSABLE_ORACLE_PROCESS_ONLY';providerCountDuringCapture=0;defaultCodePage=65001};utf8Aliases=$aliases;otherCoreLibAliases=$otherNames;requestCount=$requests.Count;rows=$rows.ToArray();qualification='SELECTED_PROVIDER_FREE_UTF8_LOOKUPS_ONLY; OTHER_ENCODINGS_PROVIDER_REGISTRATION_UTF7_SWITCH_UNICODE_NAME_CASING_FULL_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -EscapeHandling EscapeNonAscii)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS pinned UTF-8 encoding lookups: $($requests.Count) requests; $($rows.Count) configurations"
